namespace bettercpp{class TearRuntime{private:std::string c;void log(std::string s,std::string i){std::cout<<"[TEAR-RUNTIME]["<<s<<"] "<<i<<std::endl;}public:TearRuntime(std::string cmd){c=cmd;}void run(){std::cout<<"=== TEAR: Terminal Runtime ==="<<std::endl;log("INIT","Command: "+c);auto t1=std::chrono::high_resolution_clock::now();int e=std::system(c.c_str());auto t2=std::chrono::high_resolution_clock::now();auto d=std::chrono::duration_cast<std::chrono::milliseconds>(t2-t1).count();std::cout<<"------------------------------"<<std::endl;if(e==0){log("SUCCESS","Exit code: 0");}else{log("WARN","Exit code: "+std::to_string(e));}log("ANALYSIS","Time: "+std::to_string(d)+" ms");}};}int main(int c,char* v[]){std::string cmd=(c>1)?v[1]:"echo 'TEAR Runtime Active'";bettercpp::TearRuntime r(cmd);r.run();return 0;}